/// Returns the canonical (English) builtin name for a possibly-localized name.
/// If the name is not an alias, returns it unchanged.
pub fn builtin_canonical(name: &str) -> &str {
    for &(alias, canonical) in BUILTIN_ALIASES {
        if alias == name {
            return canonical;
        }
    }
    name
}

/// Returns alias→canonical map for runtime env registration.
pub fn builtin_aliases() -> Vec<(String, String)> {
    BUILTIN_ALIASES
        .iter()
        .map(|&(a, c)| (a.into(), c.into()))
        .collect()
}

// ---- Standard Prelude ----
// Auto-imported definitions for every Futuruna program (unless --no-prelude).
// These are parsed once and prepended to the user's program.
// User-defined functions/types with the same name shadow prelude versions.
const TAU_PRELUDE: &str = r#"
-- Futuruna Standard Prelude (auto-imported)
-- Types available to every Futuruna program without explicit definition.
-- Note: # List(a) is NOT included — programs that want Cons/Nil define it
-- themselves; programs that use List(Int) in type annotations get Vec<i64>.

# Option(a) = None | Some(a)
# Result(a, e) = Ok(a) | Err(e)
# Pair(a, b) = Pair(fst: a, snd: b)

-- A serializable, compiler-checked pointer to a declaration or structural
-- member in the current program. `refof(...)` constructs these values.
# ProgramReference = ProgramSymbolReference(name: String) | ProgramTypeReference(name: String) | ProgramMemberReference(root_type: String, path: String)

-- Marker trait for values deliberately exposed through a meta label.
# trait Meta {}

-- Marker trait for typed role variants nested inside a Meta value.
# trait MetaRole {}

-- Option functions

> unwrap_or(opt: Option(a), default: a) -> a {
    match opt {
        | None -> default
        | Some(x) -> x
    }
}

> is_some(opt: Option(a)) -> Bool {
    match opt {
        | None -> false
        | Some(_) -> true
    }
}

> is_none(opt: Option(a)) -> Bool {
    match opt {
        | None -> true
        | Some(_) -> false
    }
}

-- Math

> max_int(a: Int, b: Int) -> Int {
    if a >= b { a } else { b }
}

> min_int(a: Int, b: Int) -> Int {
    if a <= b { a } else { b }
}

> clamp(x: Int, lo: Int, hi: Int) -> Int {
    if x < lo { lo } else { if x > hi { hi } else { x } }
}

-- Composition

> identity(x: a) -> a { x }

-- Built-in effects

# effect Console {
    > say(msg: String) -> ()
    > ask(prompt: String) -> String
}
"#;

/// Parse the standard prelude into a list of statements.
/// Returns only definition and type declaration statements.
pub fn parse_prelude() -> Vec<Stmt> {
    let mut lexer = Lexer::new(TAU_PRELUDE);
    let tokens = lexer.tokenize();
    let mut parser = Parser::new(tokens, TAU_PRELUDE);
    match parser.parse_program() {
        Ok(stmts) => stmts
            .into_iter()
            .filter(|s| matches!(s, Stmt::Defn(_) | Stmt::TypeDecl(_)))
            .collect(),
        Err(e) => {
            eprintln!("BUG: prelude parse error: {}", e);
            vec![]
        }
    }
}

/// Prepend prelude statements to user statements, skipping prelude definitions
/// that the user has already defined (user definitions take priority).
pub fn prepend_prelude(prelude: Vec<Stmt>, user_stmts: &[Stmt]) -> Vec<Stmt> {
    // Collect names defined by the user
    let mut user_names: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    for s in user_stmts {
        match s {
            Stmt::Defn(Defn::Fn { name, .. }) => {
                user_names.insert(name.clone());
            }
            Stmt::TypeDecl(TypeDecl::ADT { name, .. }) => {
                user_names.insert(name.clone());
            }
            Stmt::TypeDecl(TypeDecl::TraitDecl { name, .. }) => {
                user_names.insert(name.clone());
            }
            Stmt::TypeDecl(TypeDecl::EffectDecl { name, .. }) => {
                user_names.insert(name.clone());
            }
            _ => {}
        }
    }
    // Only include prelude stmts whose name isn't shadowed by the user
    let mut result: Vec<Stmt> = prelude
        .into_iter()
        .filter(|s| {
            let name = match s {
                Stmt::Defn(Defn::Fn { name, .. }) => Some(name.as_str()),
                Stmt::TypeDecl(TypeDecl::ADT { name, .. }) => Some(name.as_str()),
                Stmt::TypeDecl(TypeDecl::TraitDecl { name, .. }) => Some(name.as_str()),
                Stmt::TypeDecl(TypeDecl::EffectDecl { name, .. }) => Some(name.as_str()),
                _ => None,
            };
            name.map(|n| !user_names.contains(n)).unwrap_or(true)
        })
        .collect();
    result.extend_from_slice(user_stmts);
    result
}

pub enum TplPart {
    Lit(String),
    Interp(String),
}

pub struct Lexer {
    pub chars: Vec<char>,
    pub pos: usize,
    pub line: usize,
    pub col: usize,
    pub keywords: KeywordTable,
}

impl Lexer {
    pub fn new(source: &str) -> Self {
        let keywords = detect_language(source);
        Lexer {
            chars: source.chars().collect(),
            pos: 0,
            line: 1,
            col: 1,
            keywords,
        }
    }

    pub fn with_keywords(source: &str, keywords: KeywordTable) -> Self {
        Lexer {
            chars: source.chars().collect(),
            pos: 0,
            line: 1,
            col: 1,
            keywords,
        }
    }

    pub fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    pub fn peek2(&self) -> Option<char> {
        self.chars.get(self.pos + 1).copied()
    }

    pub fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    pub fn advance(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied()?;
        self.pos += 1;
        if c == '\n' {
            self.line += 1;
            self.col = 1;
        } else {
            self.col += 1;
        }
        Some(c)
    }

    pub fn tokenize(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            self.skip_whitespace_not_newline();
            let line = self.line;
            let col = self.col;

            let c = match self.peek() {
                Some(c) => c,
                None => {
                    tokens.push(Token::new(TokenKind::Eof, "", line, col));
                    break;
                }
            };

            // Block comments: ---- ... ----
            if c == '-'
                && self.peek2() == Some('-')
                && self.peek_at(2) == Some('-')
                && self.peek_at(3) == Some('-')
            {
                // Consume the opening ----
                self.advance();
                self.advance();
                self.advance();
                self.advance();
                // Scan until closing ----
                loop {
                    match self.peek() {
                        None => break, // EOF — unclosed block comment
                        Some('-')
                            if self.peek2() == Some('-')
                                && self.peek_at(2) == Some('-')
                                && self.peek_at(3) == Some('-') =>
                        {
                            self.advance();
                            self.advance();
                            self.advance();
                            self.advance();
                            break;
                        }
                        _ => {
                            self.advance();
                        }
                    }
                }
                continue;
            }

            // Line comments: -- to end of line
            if c == '-' && self.peek2() == Some('-') {
                while let Some(c) = self.peek() {
                    if c == '\n' {
                        break;
                    }
                    self.advance();
                }
                continue;
            }

            // Newlines become semicolons (statement separators)
            if c == '\n' {
                self.advance();
                // Collapse multiple newlines
                while self.peek() == Some('\n') {
                    self.advance();
                }
                // Don't emit semi at start or after another semi
                if let Some(last) = tokens.last() {
                    if last.kind != TokenKind::Semi
                        && last.kind != TokenKind::LBrace
                        && last.kind != TokenKind::Start
                    {
                        tokens.push(Token::new(TokenKind::Semi, "\n", line, col));
                    }
                }
                continue;
            }

            // Two-character operators
            // ?. (safe call) and ?: (elvis) — must come before single-char ? handling
            if c == '?' && self.peek2() == Some('.') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::SafeCall, "?.", line, col));
                continue;
            }
            if c == '?' && self.peek2() == Some(':') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Elvis, "?:", line, col));
                continue;
            }
            if c == '-' && self.peek2() == Some('>') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Arrow, "->", line, col));
                continue;
            }
            if c == '<' && self.peek2() == Some('-') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Send, "<-", line, col));
                continue;
            }
            if c == '=' && self.peek2() == Some('>') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::FatArrow, "=>", line, col));
                continue;
            }
            if c == '=' && self.peek2() == Some('=') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Op, "==", line, col));
                continue;
            }
            if c == '!' && self.peek2() == Some('=') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Op, "!=", line, col));
                continue;
            }
            if c == '>' && self.peek2() == Some('=') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Op, ">=", line, col));
                continue;
            }
            if c == '<' && self.peek2() == Some('=') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Op, "<=", line, col));
                continue;
            }
            if c == '&' && self.peek2() == Some('&') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Op, "&&", line, col));
                continue;
            }
            if c == '|' && self.peek2() == Some('|') {
                self.advance();
                self.advance();
                tokens.push(Token::new(TokenKind::Op, "||", line, col));
                continue;
            }

            // Single-character tokens
            match c {
                '(' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::LParen, "(", line, col));
                    continue;
                }
                ')' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::RParen, ")", line, col));
                    continue;
                }
                '{' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::LBrace, "{", line, col));
                    continue;
                }
                '}' => {
                    self.advance();
                    // Remove preceding semi before }
                    if let Some(last) = tokens.last() {
                        if last.kind == TokenKind::Semi {
                            tokens.pop();
                        }
                    }
                    tokens.push(Token::new(TokenKind::RBrace, "}", line, col));
                    continue;
                }
                '[' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::LBracket, "[", line, col));
                    continue;
                }
                ']' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::RBracket, "]", line, col));
                    continue;
                }
                ',' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::Comma, ",", line, col));
                    continue;
                }
                ';' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::Semi, ";", line, col));
                    continue;
                }
                ':' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::Colon, ":", line, col));
                    continue;
                }
                '.' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::Dot, ".", line, col));
                    continue;
                }
                '#' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::Hash, "#", line, col));
                    continue;
                }
                '@' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::At, "@", line, col));
                    continue;
                }
                '&' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::Amp, "&", line, col));
                    continue;
                }
                '~' => {
                    self.advance();
                    tokens.push(Token::new(TokenKind::Tilde, "~", line, col));
                    continue;
                }
                '|' => {
                    self.advance();
                    if self.pos < self.chars.len() && self.chars[self.pos] == '>' {
                        self.advance();
                        tokens.push(Token::new(TokenKind::PipeGt, "|>", line, col));
                    } else {
                        tokens.push(Token::new(TokenKind::Pipe, "|", line, col));
                    }
                    continue;
                }
                '>' => {
                    self.advance();
                    // Distinguish > rune (start of line) from > operator
                    let is_rune = tokens.is_empty()
                        || tokens.last().map_or(false, |t| t.kind == TokenKind::Semi);
                    if is_rune {
                        tokens.push(Token::new(TokenKind::Gt, ">", line, col));
                    } else {
                        tokens.push(Token::new(TokenKind::Op, ">", line, col));
                    }
                    continue;
                }
                '=' => {
                    self.advance();
                    // Distinguish = rune (start of statement) from = operator
                    let is_rune = tokens.is_empty()
                        || tokens.last().map_or(false, |t| {
                            t.kind == TokenKind::Semi || t.kind == TokenKind::LBrace
                        });
                    if is_rune {
                        tokens.push(Token::new(TokenKind::Eq, "=", line, col));
                    } else {
                        tokens.push(Token::new(TokenKind::Op, "=", line, col));
                    }
                    continue;
                }
                _ => {}
            }

            // Operators: + - * / % < ! ?
            if "+-*/%<!?~^".contains(c) {
                self.advance();
                tokens.push(Token::new(TokenKind::Op, c.to_string(), line, col));
                continue;
            }

            // Numbers
            if c.is_ascii_digit() {
                let s = self.read_number();
                let kind = if s.contains('.') {
                    TokenKind::Float_
                } else {
                    TokenKind::Int_
                };
                tokens.push(Token::new(kind, s, line, col));
                continue;
            }

            // String literals
            if c == '"' {
                // Check for triple-quoted string: """..."""
                // c is from peek() (not yet consumed), so check pos+1 and pos+2
                if self.peek_at(1) == Some('"') && self.peek_at(2) == Some('"') {
                    self.advance(); // consume first "
                    self.advance(); // consume second "
                    self.advance(); // consume third "
                    let parts = self.read_triple_string();
                    // Desugar template parts into concatenation tokens
                    let mut first = true;
                    for part in &parts {
                        match part {
                            TplPart::Lit(s) => {
                                if !first {
                                    tokens.push(Token::new(TokenKind::Op, "+", line, col));
                                }
                                tokens.push(Token::new(TokenKind::String_, s.clone(), line, col));
                                first = false;
                            }
                            TplPart::Interp(expr_src) => {
                                if !first {
                                    tokens.push(Token::new(TokenKind::Op, "+", line, col));
                                }
                                // Desugar {{expr}} to show(expr)
                                tokens.push(Token::new(TokenKind::Ident, "show", line, col));
                                tokens.push(Token::new(TokenKind::LParen, "(", line, col));
                                // Lex the interpolated expression (inherit parent's keywords)
                                let mut sub = Lexer::with_keywords(expr_src, self.keywords.clone());
                                let sub_tokens = sub.tokenize();
                                for st in &sub_tokens {
                                    if st.kind != TokenKind::Eof {
                                        tokens.push(Token::new(
                                            st.kind,
                                            st.text.clone(),
                                            line,
                                            col,
                                        ));
                                    }
                                }
                                tokens.push(Token::new(TokenKind::RParen, ")", line, col));
                                first = false;
                            }
                        }
                    }
                    // If the template was empty or all-interpolation, ensure at least one string
                    if first {
                        tokens.push(Token::new(TokenKind::String_, String::new(), line, col));
                    }
                    continue;
                }
                let s = self.read_string();
                tokens.push(Token::new(TokenKind::String_, s, line, col));
                continue;
            }

            // Char literals
            if c == '\'' {
                let s = self.read_char_lit();
                tokens.push(Token::new(TokenKind::Char_, s, line, col));
                continue;
            }

            // Structural path selector used by pathof(...::$variant).
            if c == '$'
                && self
                    .peek2()
                    .is_some_and(|next| next.is_alphabetic() || next == '_')
            {
                self.advance();
                let word = self.read_word();
                tokens.push(Token::new(
                    TokenKind::Ident,
                    format!("${}", word),
                    line,
                    col,
                ));
                continue;
            }

            // Words: identifiers, keywords, type names, booleans
            // Uses the keyword table (set by @ sprog / @ language declaration)
            if c.is_alphabetic() || c == '_' {
                let word = self.read_word();
                let (text, kind) = if let Some((canonical, kw_kind)) = self.keywords.get(&word) {
                    // Keyword or boolean — normalize to canonical English form
                    (canonical.clone(), *kw_kind)
                } else if word.starts_with(|c: char| c.is_uppercase()) {
                    (word.clone(), TokenKind::Type)
                } else {
                    (word.clone(), TokenKind::Ident)
                };
                tokens.push(Token::new(kind, text, line, col).with_source_text(word));
                continue;
            }

            // Skip unknown characters
            self.advance();
        }

        tokens
    }

    pub fn skip_whitespace_not_newline(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\r' {
                self.advance();
            } else {
                break;
            }
        }
    }

    pub fn read_word(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_alphanumeric() || c == '_' {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        s
    }

    /// Read a triple-quoted string `"""..."""`.
    /// Opening `"""` already consumed. Strips leading/trailing newline.
    /// Supports `{{expr}}` interpolation.
    pub fn read_triple_string(&mut self) -> Vec<TplPart> {
        // Strip leading newline
        if self.peek() == Some('\n') {
            self.advance();
        } else if self.peek() == Some('\r') {
            self.advance();
            if self.peek() == Some('\n') {
                self.advance();
            }
        }

        let mut parts: Vec<TplPart> = Vec::new();
        let mut buf = String::new();

        loop {
            match self.peek() {
                // Check for closing """
                Some('"') if self.peek_at(1) == Some('"') && self.peek_at(2) == Some('"') => {
                    self.advance();
                    self.advance();
                    self.advance();
                    break;
                }
                // Check for interpolation {{...}}
                Some('{') if self.peek_at(1) == Some('{') => {
                    self.advance();
                    self.advance(); // consume {{
                                    // Flush accumulated literal
                    if !buf.is_empty() {
                        parts.push(TplPart::Lit(std::mem::take(&mut buf)));
                    }
                    // Read expression until }}
                    let mut expr = String::new();
                    let mut depth = 0i32;
                    loop {
                        match self.peek() {
                            Some('}') if depth == 0 && self.peek_at(1) == Some('}') => {
                                self.advance();
                                self.advance();
                                break;
                            }
                            Some('{') => {
                                depth += 1;
                                expr.push('{');
                                self.advance();
                            }
                            Some('}') => {
                                depth -= 1;
                                expr.push('}');
                                self.advance();
                            }
                            Some(c) => {
                                expr.push(c);
                                self.advance();
                            }
                            None => break,
                        }
                    }
                    let trimmed = expr.trim().to_string();
                    if !trimmed.is_empty() {
                        parts.push(TplPart::Interp(trimmed));
                    }
                }
                Some(c) => {
                    buf.push(c);
                    self.advance();
                }
                None => break,
            }
        }

        // Strip trailing newline from last literal
        if buf.ends_with('\n') {
            buf.pop();
            if buf.ends_with('\r') {
                buf.pop();
            }
        }

        if !buf.is_empty() {
            parts.push(TplPart::Lit(buf));
        }

        // If no parts at all, return a single empty literal
        if parts.is_empty() {
            parts.push(TplPart::Lit(String::new()));
        }

        parts
    }

    pub fn read_number(&mut self) -> String {
        let mut s = String::new();
        let mut has_dot = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c);
                self.advance();
            } else if c == '.' && !has_dot {
                // Check it's not a method call like 42.foo
                if self.peek2().map_or(false, |c2| c2.is_ascii_digit()) {
                    has_dot = true;
                    s.push(c);
                    self.advance();
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        s
    }

    pub fn read_string(&mut self) -> String {
        self.advance(); // consume opening "
        let mut s = String::new();
        loop {
            match self.advance() {
                Some('"') => break,
                Some('\\') => match self.advance() {
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('\\') => s.push('\\'),
                    Some('"') => s.push('"'),
                    Some(c) => {
                        s.push('\\');
                        s.push(c);
                    }
                    None => break,
                },
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    pub fn read_char_lit(&mut self) -> String {
        self.advance(); // consume opening '
        let c = match self.advance() {
            Some('\\') => match self.advance() {
                Some('n') => '\n',
                Some('t') => '\t',
                Some('\\') => '\\',
                Some('\'') => '\'',
                Some(c) => c,
                None => ' ',
            },
            Some(c) => c,
            None => ' ',
        };
        if self.peek() == Some('\'') {
            self.advance();
        }
        c.to_string()
    }
}

// ============================================================================
// PART 2b: SPANS & DIAGNOSTICS
// ============================================================================

/// Source location span — character offsets into source text.
/// Use `Span::to_line_col()` to convert to human-readable line:col.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Span {
    pub start: usize, // character offset (0-based)
    pub end: usize,   // character offset (exclusive)
}

impl Span {
    pub fn new(start: usize, end: usize) -> Self {
        Span { start, end }
    }

    /// Dummy span for AST nodes not yet tracked.
    pub fn dummy() -> Self {
        Span { start: 0, end: 0 }
    }

    pub fn is_dummy(&self) -> bool {
        self.start == 0 && self.end == 0
    }

    /// Merge two spans into one covering both.
    pub fn merge(self, other: Span) -> Span {
        if self.is_dummy() {
            return other;
        }
        if other.is_dummy() {
            return self;
        }
        Span {
            start: self.start.min(other.start),
            end: self.end.max(other.end),
        }
    }

    /// Convert character offset to 1-based (line, col) using source text.
    pub fn start_line_col(&self, source: &str) -> (usize, usize) {
        char_offset_to_line_col(source, self.start)
    }

    pub fn end_line_col(&self, source: &str) -> (usize, usize) {
        char_offset_to_line_col(source, self.end)
    }
}

/// Convert a character offset to 1-based (line, col).
pub fn char_offset_to_line_col(source: &str, offset: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for (i, ch) in source.chars().enumerate() {
        if i >= offset {
            break;
        }
        if ch == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

/// Backwards-compatible alias for older call sites. Parser spans are character
/// offsets, so new code should call `char_offset_to_line_col`.
pub fn byte_offset_to_line_col(source: &str, offset: usize) -> (usize, usize) {
    char_offset_to_line_col(source, offset)
}

// ============================================================================
// PART 2c: META COMMENTS
// ============================================================================

/// Machine-readable anchors encoded as comments.
///
/// Meta comments are intentionally comments, so they remain backward-compatible
/// with the language parser. Tooling can scan raw source and build this side
/// index without changing evaluation semantics.
///
/// The canonical metadata shape contains only a label and one binding to a
/// ground Futuruna value whose root type implements `Meta`. Metadata structure,
/// including role variants from types implementing `MetaRole`, belongs in that
/// value rather than in the comment grammar:
///
/// ```text
/// --@label:label::meta:typed_binding--
/// --@begin:label--
/// --@end:label--
/// ```
///
/// Direct role chains and older marker spellings remain accepted only for
/// source compatibility:
///
/// ```text
/// --@label:label::role:binding::role:another_binding--
/// --@meta::label::role:binding--
/// --@source::label::meta:source_binding--
/// --@begin::label--
/// --@end::label--
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaAttribute {
    pub role: String,
    pub binding_name: String,
}

/// A statically resolvable Futuruna value referenced by a meta comment.
///
/// The metadata index keeps this structural form so audit tooling does not
/// need to parse the compatibility-oriented `static_value` rendering.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MetaValue {
    Integer(i64),
    Float(String),
    String(String),
    Character(char),
    Boolean(bool),
    Unit,
    Constructor {
        name: String,
        qualified_type: String,
        applied: bool,
        arguments: Vec<MetaValueArgument>,
    },
    List(Vec<MetaValue>),
    Tuple(Vec<MetaValue>),
    Unary {
        operator: String,
        value: Box<MetaValue>,
    },
}

impl MetaValue {
    pub fn to_source(&self) -> String {
        match self {
            Self::Integer(value) => value.to_string(),
            Self::Float(value) => value.clone(),
            Self::String(value) => format!("{:?}", value),
            Self::Character(value) => format!("{:?}", value),
            Self::Boolean(value) => {
                if *value {
                    "True".to_string()
                } else {
                    "False".to_string()
                }
            }
            Self::Unit => "()".to_string(),
            Self::Constructor {
                name,
                qualified_type: _,
                applied,
                arguments,
            } => {
                if !applied {
                    return name.clone();
                }
                let arguments = arguments
                    .iter()
                    .map(|argument| match &argument.field {
                        Some(field) => format!("{} = {}", field, argument.value.to_source()),
                        None => argument.value.to_source(),
                    })
                    .collect::<Vec<_>>()
                    .join(", ");
                format!("{}({})", name, arguments)
            }
            Self::List(items) => {
                let items = items
                    .iter()
                    .map(Self::to_source)
                    .collect::<Vec<_>>()
                    .join(", ");
                format!("[{}]", items)
            }
            Self::Tuple(items) => {
                let items = items
                    .iter()
                    .map(Self::to_source)
                    .collect::<Vec<_>>()
                    .join(", ");
                format!("({})", items)
            }
            Self::Unary { operator, value } => format!("{}{}", operator, value.to_source()),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaValueArgument {
    pub field: Option<String>,
    pub binding_name: Option<String>,
    pub value: MetaValue,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaTypedValue<'a> {
    pub value_path: String,
    pub qualified_type: &'a str,
    pub value: &'a MetaValue,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaRoleValue<'a> {
    pub attachment_path: String,
    pub role_path: String,
    pub value_path: String,
    pub role: String,
    pub binding_name: Option<&'a str>,
    pub attachment: &'a MetaValue,
    pub value: &'a MetaValue,
}

#[deprecated(note = "use MetaRoleValue; MetaAttachment is compatibility-only")]
pub type MetaAttachmentValue<'a> = MetaRoleValue<'a>;

impl MetaValue {
    pub fn typed_values(&self) -> Vec<MetaTypedValue<'_>> {
        let mut values = Vec::new();
        self.collect_typed_values("$", &mut values);
        values
    }

    pub fn typed_values_by_type(&self, qualified_type: &str) -> Vec<MetaTypedValue<'_>> {
        self.typed_values()
            .into_iter()
            .filter(|value| value.qualified_type == qualified_type)
            .collect()
    }

    pub fn attachments(&self) -> Vec<MetaRoleValue<'_>> {
        self.attachments_with_role_types(&BTreeSet::new())
    }

    pub fn attachments_with_role_types(
        &self,
        meta_role_types: &BTreeSet<String>,
    ) -> Vec<MetaRoleValue<'_>> {
        let mut attachments = Vec::new();
        self.collect_attachments("$", meta_role_types, &mut attachments);
        attachments
    }

    pub fn qualified_type(&self) -> Option<&str> {
        match self {
            Self::Constructor { qualified_type, .. } => Some(qualified_type),
            _ => None,
        }
    }

    fn collect_typed_values<'a>(&'a self, value_path: &str, values: &mut Vec<MetaTypedValue<'a>>) {
        match self {
            Self::Constructor {
                qualified_type,
                arguments,
                ..
            } => {
                values.push(MetaTypedValue {
                    value_path: value_path.to_string(),
                    qualified_type,
                    value: self,
                });
                for (index, argument) in arguments.iter().enumerate() {
                    let child_path = match argument.field.as_deref() {
                        Some(field) => format!("{value_path}.{field}"),
                        None => format!("{value_path}[{index}]"),
                    };
                    argument.value.collect_typed_values(&child_path, values);
                }
            }
            Self::List(items) | Self::Tuple(items) => {
                for (index, item) in items.iter().enumerate() {
                    item.collect_typed_values(&format!("{value_path}[{index}]"), values);
                }
            }
            Self::Unary { value, .. } => value.collect_typed_values(value_path, values),
            _ => {}
        }
    }

    fn collect_attachments<'a>(
        &'a self,
        value_path: &str,
        meta_role_types: &BTreeSet<String>,
        attachments: &mut Vec<MetaRoleValue<'a>>,
    ) {
        match self {
            Self::Constructor {
                name,
                qualified_type,
                applied: true,
                arguments,
                ..
            } => {
                if name == "MetaAttachment" {
                    let role = arguments
                        .iter()
                        .find(|argument| argument.field.as_deref() == Some("role"));
                    let value = arguments
                        .iter()
                        .find(|argument| argument.field.as_deref() == Some("value"));
                    if arguments.len() == 2 {
                        if let (Some(role), Some(value)) = (role, value) {
                            if let Some(role_identifier) = meta_role_identifier(&role.value) {
                                attachments.push(MetaRoleValue {
                                    attachment_path: value_path.to_string(),
                                    role_path: format!("{value_path}.role"),
                                    value_path: format!("{value_path}.value"),
                                    role: role_identifier,
                                    binding_name: value.binding_name.as_deref(),
                                    attachment: self,
                                    value: &value.value,
                                });
                            }
                        }
                    }
                } else if meta_role_types.contains(qualified_type) {
                    let value = arguments
                        .iter()
                        .find(|argument| argument.field.as_deref() == Some("value"));
                    if arguments.len() == 1 {
                        if let Some(value) = value {
                            attachments.push(MetaRoleValue {
                                attachment_path: value_path.to_string(),
                                role_path: format!("{value_path}.$variant"),
                                value_path: format!("{value_path}.value"),
                                role: meta_constructor_role_identifier(name),
                                binding_name: value.binding_name.as_deref(),
                                attachment: self,
                                value: &value.value,
                            });
                        }
                    }
                }
                for (index, argument) in arguments.iter().enumerate() {
                    let child_path = match argument.field.as_deref() {
                        Some(field) => format!("{value_path}.{field}"),
                        None => format!("{value_path}[{index}]"),
                    };
                    argument
                        .value
                        .collect_attachments(&child_path, meta_role_types, attachments);
                }
            }
            Self::Constructor { .. } => {}
            Self::List(items) | Self::Tuple(items) => {
                for (index, item) in items.iter().enumerate() {
                    item.collect_attachments(
                        &format!("{value_path}[{index}]"),
                        meta_role_types,
                        attachments,
                    );
                }
            }
            Self::Unary { value, .. } => {
                value.collect_attachments(value_path, meta_role_types, attachments)
            }
            _ => {}
        }
    }
}

fn meta_role_identifier(value: &MetaValue) -> Option<String> {
    match value {
        MetaValue::String(value) if !value.trim().is_empty() => Some(value.trim().to_string()),
        MetaValue::Constructor {
            name,
            applied: false,
            arguments,
            ..
        } if arguments.is_empty() => Some(meta_constructor_role_identifier(name)),
        MetaValue::Constructor {
            applied: true,
            arguments,
            ..
        } => arguments.iter().find_map(|argument| {
            matches!(argument.field.as_deref(), Some("id" | "name"))
                .then_some(&argument.value)
                .and_then(|value| match value {
                    MetaValue::String(value) if !value.trim().is_empty() => {
                        Some(value.trim().to_string())
                    }
                    _ => None,
                })
        }),
        _ => None,
    }
}

fn meta_constructor_role_identifier(name: &str) -> String {
    let chars = name.chars().collect::<Vec<_>>();
    let mut identifier = String::new();
    for (index, character) in chars.iter().copied().enumerate() {
        let previous = index
            .checked_sub(1)
            .and_then(|index| chars.get(index))
            .copied();
        let next = chars.get(index + 1).copied();
        if character.is_uppercase()
            && index > 0
            && (previous.is_some_and(|value| value.is_lowercase() || value.is_numeric())
                || next.is_some_and(char::is_lowercase))
        {
            identifier.push('_');
        }
        identifier.extend(character.to_lowercase());
    }
    identifier
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaComment {
    pub kind: String,
    pub label: String,
    pub attrs: Vec<MetaAttribute>,
    pub line: usize,
    pub col: usize,
    pub raw: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaReference {
    pub label: String,
    pub role: String,
    pub binding_name: String,
    pub qualified_type: Option<String>,
    pub static_value: Option<String>,
    pub static_data: Option<MetaValue>,
    pub definition_file: Option<String>,
    pub definition_line: Option<usize>,
    pub comment_line: usize,
    /// Named Futuruna sum types explicitly implementing `MetaRole` in the
    /// attachment's module graph. Their applied variant name is the role and
    /// their sole named `value` field is the attached payload.
    pub meta_role_types: BTreeSet<String>,
}

impl MetaReference {
    pub fn typed_values(&self) -> Vec<MetaTypedValue<'_>> {
        self.static_data
            .as_ref()
            .map(MetaValue::typed_values)
            .unwrap_or_default()
    }

    pub fn typed_values_by_type(&self, qualified_type: &str) -> Vec<MetaTypedValue<'_>> {
        self.static_data
            .as_ref()
            .map(|value| value.typed_values_by_type(qualified_type))
            .unwrap_or_default()
    }

    pub fn attachments(&self) -> Vec<MetaRoleValue<'_>> {
        self.static_data
            .as_ref()
            .map(|value| value.attachments_with_role_types(&self.meta_role_types))
            .unwrap_or_default()
    }

    pub fn matches(&self, qualified_type: Option<&str>, role: Option<&str>) -> bool {
        let direct_match = role.is_none_or(|expected| self.role == expected)
            && qualified_type.is_none_or(|expected| {
                self.qualified_type.as_deref() == Some(expected)
                    || !self.typed_values_by_type(expected).is_empty()
            });
        direct_match
            || self.attachments().into_iter().any(|attachment| {
                role.is_none_or(|expected| attachment.role == expected)
                    && qualified_type.is_none_or(|expected| {
                        !attachment
                            .attachment
                            .typed_values_by_type(expected)
                            .is_empty()
                    })
            })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaAnchor {
    pub kind: String,
    pub label: String,
    pub references: Vec<MetaReference>,
    pub comment_line: usize,
    pub text_begin_marker_line: Option<usize>,
    pub text_end_marker_line: Option<usize>,
    pub text_start_line: Option<usize>,
    pub text_end_line: Option<usize>,
    pub text: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaSymbol {
    pub kind: String,
    pub name: String,
    pub line: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaCodeSpan {
    pub label: String,
    pub begin_marker_line: usize,
    pub end_marker_line: usize,
    pub code_start_line: usize,
    pub code_end_line: usize,
    pub symbols: Vec<MetaSymbol>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaDiagnostic {
    pub line: usize,
    pub message: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetaIndex {
    pub comments: Vec<MetaComment>,
    pub anchors: Vec<MetaAnchor>,
    pub spans: Vec<MetaCodeSpan>,
    pub diagnostics: Vec<MetaDiagnostic>,
    /// Pure ground bindings needed to construct resolved metadata values.
    ///
    /// Compiler backends may treat these as compile-time data when none of
    /// the bindings are also reachable from executable code.
    pub resolved_binding_names: BTreeSet<String>,
}

impl MetaIndex {
    pub fn references(&self) -> Vec<&MetaReference> {
        self.anchors
            .iter()
            .flat_map(|anchor| anchor.references.iter())
            .collect()
    }

    pub fn references_by_type(&self, qualified_type: &str) -> Vec<&MetaReference> {
        self.references_matching(Some(qualified_type), None)
    }

    pub fn references_by_role(&self, role: &str) -> Vec<&MetaReference> {
        self.references_matching(None, Some(role))
    }

    pub fn references_matching(
        &self,
        qualified_type: Option<&str>,
        role: Option<&str>,
    ) -> Vec<&MetaReference> {
        self.anchors
            .iter()
            .flat_map(|anchor| anchor.references.iter())
            .filter(|reference| reference.matches(qualified_type, role))
            .collect()
    }

    pub fn anchors_for_label(&self, label: &str) -> Vec<&MetaAnchor> {
        self.anchors
            .iter()
            .filter(|anchor| anchor.label == label)
            .collect()
    }

    pub fn spans_for_label(&self, label: &str) -> Vec<&MetaCodeSpan> {
        self.spans
            .iter()
            .filter(|span| span.label == label)
            .collect()
    }

    pub fn spans_for_reference(&self, reference: &MetaReference) -> Vec<&MetaCodeSpan> {
        self.spans_for_label(&reference.label)
    }
}

#[derive(Debug, Clone)]
struct ActiveMetaCodeSpan {
    label: String,
    begin_marker_line: usize,
    code_start_line: usize,
}

pub fn scan_meta_comments(source: &str) -> MetaIndex {
    scan_meta_comments_with_dir(source, None)
}

pub fn scan_meta_comments_with_dir(source: &str, source_dir: Option<String>) -> MetaIndex {
    let mut lexer = Lexer::new(source);
    let tokens = lexer.tokenize();
    let mut parser = Parser::new(tokens, source);
    match parser.parse_program() {
        Ok(stmts) => scan_meta_comments_with_dir_from_stmts(source, &stmts, source_dir),
        Err(_) => {
            let mut index = scan_meta_comment_structure(source);
            resolve_meta_references(source, source_dir, &mut index);
            index
        }
    }
}

fn scan_meta_comments_with_dir_from_stmts(
    source: &str,
    stmts: &[Stmt],
    source_dir: Option<String>,
) -> MetaIndex {
    scan_meta_comments_with_dir_from_stmts_and_checker(source, stmts, source_dir, None)
}

fn scan_meta_comments_with_dir_from_stmts_and_checker(
    source: &str,
    stmts: &[Stmt],
    source_dir: Option<String>,
    checker: Option<&TypeChecker>,
) -> MetaIndex {
    let mut index = scan_meta_comment_structure_from_stmts(source, stmts);
    resolve_meta_references_from_stmts_and_checker(source, stmts, source_dir, &mut index, checker);
    index
}

/// Scan local metadata and matching anchors from recursively imported modules.
///
/// Imported metadata is opt-in by label so consumers can compose annotations
/// for a known entry without inheriting unrelated anchors from their complete
/// dependency graph. Every imported anchor is resolved in the module where it
/// is declared before being added to the combined index.
pub fn scan_meta_comments_with_imported_labels(
    source: &str,
    source_dir: Option<String>,
    labels: &BTreeSet<String>,
) -> MetaIndex {
    let mut lexer = Lexer::new(source);
    let tokens = lexer.tokenize();
    let mut parser = Parser::new(tokens, source);
    let Ok(stmts) = parser.parse_program() else {
        return scan_meta_comments_with_dir(source, source_dir);
    };
    scan_meta_comments_with_imported_labels_from_stmts(source, &stmts, source_dir, labels, None)
}

pub(crate) fn scan_meta_comments_with_imported_labels_and_checker(
    source: &str,
    stmts: &[Stmt],
    source_dir: Option<String>,
    labels: &BTreeSet<String>,
    checker: &TypeChecker,
) -> MetaIndex {
    scan_meta_comments_with_imported_labels_from_stmts(
        source,
        stmts,
        source_dir,
        labels,
        Some(checker),
    )
}

fn scan_meta_comments_with_imported_labels_from_stmts(
    source: &str,
    stmts: &[Stmt],
    source_dir: Option<String>,
    labels: &BTreeSet<String>,
    checker: Option<&TypeChecker>,
) -> MetaIndex {
    let mut index = scan_meta_comments_with_dir_from_stmts_and_checker(
        source,
        stmts,
        source_dir.clone(),
        checker,
    );
    let mut target_labels = labels.clone();
    for span in &index.spans {
        if span
            .symbols
            .iter()
            .any(|symbol| labels.contains(&symbol.name))
        {
            target_labels.insert(span.label.clone());
        }
    }
    collect_imported_meta_anchors_from_stmts(
        stmts,
        source_dir.as_deref(),
        &target_labels,
        &mut BTreeSet::new(),
        &mut index,
        checker,
    );
    index
}

fn collect_imported_meta_anchors_from_stmts(
    stmts: &[Stmt],
    source_dir: Option<&str>,
    labels: &BTreeSet<String>,
    visited: &mut BTreeSet<String>,
    index: &mut MetaIndex,
    checker: Option<&TypeChecker>,
) {
    let Some(source_dir) = source_dir else {
        return;
    };

    for stmt in stmts {
        let Stmt::Import(import_path) = stmt else {
            continue;
        };
        let Some(file_path) = Interpreter::resolve_import_path_for_source(import_path, source_dir)
        else {
            continue;
        };
        let canonical = std::fs::canonicalize(&file_path)
            .map(|path| path.to_string_lossy().to_string())
            .unwrap_or_else(|_| file_path.clone());
        if !visited.insert(canonical) {
            continue;
        }
        let Ok(imported_module) = parse_source_module_file_cached(Path::new(&file_path)) else {
            continue;
        };
        let imported_source = imported_module.source();
        let imported_dir = std::path::Path::new(&file_path)
            .parent()
            .map(|parent| parent.to_string_lossy().to_string())
            .unwrap_or_else(|| ".".to_string());

        if imported_source
            .lines()
            .any(|line| meta_comment_line_mentions_labels(line, labels))
        {
            let parsed_rule_symbols = imported_source
                .lines()
                .any(|line| {
                    line.trim_start().starts_with("--@begin")
                        && meta_comment_line_mentions_labels(line, labels)
                })
                .then(|| {
                    let mut symbols = BTreeMap::new();
                    let line_starts = source_line_start_offsets(imported_source);
                    collect_parsed_meta_rule_symbols(
                        imported_module.statements(),
                        &line_starts,
                        &mut symbols,
                    );
                    symbols
                });
            let mut imported_index =
                scan_meta_comment_structure_with_rule_symbols(imported_source, parsed_rule_symbols);
            imported_index
                .comments
                .retain(|comment| labels.contains(&comment.label));
            imported_index
                .anchors
                .retain(|anchor| labels.contains(&anchor.label));
            imported_index
                .spans
                .retain(|span| labels.contains(&span.label));
            if !imported_index.anchors.is_empty() {
                resolve_meta_references_from_stmts_and_checker(
                    imported_source,
                    imported_module.statements(),
                    Some(imported_dir.clone()),
                    &mut imported_index,
                    checker,
                );
            }
            index.comments.extend(imported_index.comments);
            index.anchors.extend(imported_index.anchors);
            index.spans.extend(imported_index.spans);
            index.diagnostics.extend(imported_index.diagnostics);
            index
                .resolved_binding_names
                .extend(imported_index.resolved_binding_names);
        }

        collect_imported_meta_anchors_from_stmts(
            imported_module.statements(),
            Some(&imported_dir),
            labels,
            visited,
            index,
            checker,
        );
    }
}

pub(crate) fn collect_imported_resolved_meta_binding_names_with_checker(
    stmts: &[Stmt],
    source_dir: Option<&str>,
    checker: &TypeChecker,
) -> BTreeSet<String> {
    let mut resolved = BTreeSet::new();
    collect_imported_resolved_meta_binding_names(
        stmts,
        source_dir,
        checker,
        &mut BTreeSet::new(),
        &mut resolved,
    );
    resolved
}

fn collect_imported_resolved_meta_binding_names(
    stmts: &[Stmt],
    source_dir: Option<&str>,
    checker: &TypeChecker,
    visited: &mut BTreeSet<String>,
    resolved: &mut BTreeSet<String>,
) {
    let Some(source_dir) = source_dir else {
        return;
    };

    for stmt in stmts {
        let Stmt::Import(import_path) = stmt else {
            continue;
        };
        let Some(file_path) = Interpreter::resolve_import_path_for_source(import_path, source_dir)
        else {
            continue;
        };
        let canonical = std::fs::canonicalize(&file_path)
            .map(|path| path.to_string_lossy().to_string())
            .unwrap_or_else(|_| file_path.clone());
        if !visited.insert(canonical) {
            continue;
        }
        let Ok(imported_module) = parse_source_module_file_cached(Path::new(&file_path)) else {
            continue;
        };
        let imported_source = imported_module.source();
        let imported_dir = Path::new(&file_path)
            .parent()
            .map(|parent| parent.to_string_lossy().to_string())
            .unwrap_or_else(|| ".".to_string());
        let imported_index = scan_meta_comments_with_dir_from_stmts_and_checker(
            imported_source,
            imported_module.statements(),
            Some(imported_dir.clone()),
            Some(checker),
        );
        resolved.extend(imported_index.resolved_binding_names);
        collect_imported_resolved_meta_binding_names(
            imported_module.statements(),
            Some(&imported_dir),
            checker,
            visited,
            resolved,
        );
    }
}

fn meta_comment_line_mentions_labels(line: &str, labels: &BTreeSet<String>) -> bool {
    let line = line.trim_start();
    line.starts_with("--@") && labels.iter().any(|label| line.contains(label))
}

fn scan_meta_comment_structure(source: &str) -> MetaIndex {
    scan_meta_comment_structure_with_rule_symbols(source, parsed_meta_rule_symbols(source))
}

fn scan_meta_comment_structure_from_stmts(source: &str, stmts: &[Stmt]) -> MetaIndex {
    let mut symbols = BTreeMap::new();
    let line_starts = source_line_start_offsets(source);
    collect_parsed_meta_rule_symbols(stmts, &line_starts, &mut symbols);
    scan_meta_comment_structure_with_rule_symbols(source, Some(symbols))
}

fn scan_meta_comment_structure_with_rule_symbols(
    source: &str,
    parsed_rule_symbols: Option<BTreeMap<usize, Vec<String>>>,
) -> MetaIndex {
    let lines: Vec<&str> = source.lines().collect();
    let mut comments = Vec::new();
    let mut anchors = Vec::new();
    let mut spans = Vec::new();
    let mut diagnostics = Vec::new();
    let mut active: Vec<ActiveMetaCodeSpan> = Vec::new();
    let mut in_block_comment = false;

    for (idx, line) in lines.iter().enumerate() {
        let line_no = idx + 1;
        let trimmed = line.trim_start();
        if in_block_comment {
            if trimmed.starts_with("----") {
                in_block_comment = false;
            }
            continue;
        }
        if trimmed.starts_with("----") {
            if trimmed.matches("----").count() < 2 {
                in_block_comment = true;
            }
            continue;
        }

        let Some(comment) = parse_meta_comment_line(line, line_no, &mut diagnostics) else {
            continue;
        };

        match comment.kind.as_str() {
            "source" | "meta" => {
                let (anchor, diagnostic) = meta_anchor_for_comment(&comment, &lines, idx + 1);
                anchors.push(anchor);
                if let Some(diagnostic) = diagnostic {
                    diagnostics.push(diagnostic);
                }
            }
            "begin" => {
                active.push(ActiveMetaCodeSpan {
                    label: comment.label.clone(),
                    begin_marker_line: line_no,
                    code_start_line: line_no + 1,
                });
            }
            "end" => {
                if let Some(pos) = active.iter().rposition(|span| span.label == comment.label) {
                    let opened = active.remove(pos);
                    let code_end_line = line_no.saturating_sub(1);
                    let symbols = scan_meta_symbols(
                        &lines,
                        opened.code_start_line,
                        code_end_line,
                        parsed_rule_symbols.as_ref(),
                    );
                    spans.push(MetaCodeSpan {
                        label: opened.label,
                        begin_marker_line: opened.begin_marker_line,
                        end_marker_line: line_no,
                        code_start_line: opened.code_start_line,
                        code_end_line,
                        symbols,
                    });
                } else {
                    diagnostics.push(MetaDiagnostic {
                        line: line_no,
                        message: format!(
                            "meta end marker for `{}` has no matching begin",
                            comment.label
                        ),
                    });
                }
            }
            _ => {}
        }

        comments.push(comment);
    }

    for span in active {
        diagnostics.push(MetaDiagnostic {
            line: span.begin_marker_line,
            message: format!("meta begin marker for `{}` has no matching end", span.label),
        });
    }

    MetaIndex {
        comments,
        anchors,
        spans,
        diagnostics,
        resolved_binding_names: BTreeSet::new(),
    }
}

fn parse_meta_comment_line(
    line: &str,
    line_no: usize,
    diagnostics: &mut Vec<MetaDiagnostic>,
) -> Option<MetaComment> {
    let trimmed_start = line.trim_start();
    let col = line.len() - trimmed_start.len() + 1;
    let body = trimmed_start.strip_prefix("--@")?;
    let Some(body) = body.strip_suffix("--") else {
        diagnostics.push(MetaDiagnostic {
            line: line_no,
            message: "meta comment must end with `--`".to_string(),
        });
        return None;
    };
    let parts: Vec<&str> = body.split("::").map(str::trim).collect();
    let (kind, label, attrs_start) =
        if let Some(label) = parts.first().and_then(|part| part.strip_prefix("label:")) {
            ("meta", label.trim(), 1)
        } else if let Some((kind, label)) = parts.first().and_then(|part| part.split_once(':')) {
            (kind.trim(), label.trim(), 1)
        } else if parts.len() >= 2 {
            (parts[0], parts[1], 2)
        } else {
            ("", "", parts.len())
        };
    if kind.is_empty() || label.is_empty() {
        diagnostics.push(MetaDiagnostic {
            line: line_no,
            message: "meta comment must use `--@label:label::meta:binding--`, `--@begin:label--`, `--@end:label--`, or a legacy compatible marker"
                .to_string(),
        });
        return None;
    }

    let mut attrs = Vec::new();
    for part in parts.iter().skip(attrs_start) {
        if part.is_empty() {
            continue;
        }
        if let Some((role, binding_name)) = part.split_once(':') {
            attrs.push(MetaAttribute {
                role: role.trim().to_string(),
                binding_name: binding_name.trim().to_string(),
            });
        } else {
            attrs.push(MetaAttribute {
                role: part.to_string(),
                binding_name: String::new(),
            });
        }
    }

    Some(MetaComment {
        kind: kind.to_string(),
        label: label.to_string(),
        attrs,
        line: line_no,
        col,
        raw: trimmed_start.to_string(),
    })
}

fn meta_anchor_for_comment(
    comment: &MetaComment,
    lines: &[&str],
    next_line_idx: usize,
) -> (MetaAnchor, Option<MetaDiagnostic>) {
    let mut text_begin_marker_line = None;
    let mut text_end_marker_line = None;
    let mut text_start_line = None;
    let mut text_end_line = None;
    let mut text_lines = Vec::new();
    let mut diagnostic = None;

    let mut idx = next_line_idx;
    while idx < lines.len() && lines[idx].trim().is_empty() {
        idx += 1;
    }

    if idx < lines.len() && lines[idx].trim_start().starts_with("----") {
        let begin_marker_line = idx + 1;
        text_begin_marker_line = Some(begin_marker_line);
        idx += 1;
        while idx < lines.len() {
            let trimmed = lines[idx].trim_start();
            if trimmed.starts_with("----") {
                text_end_marker_line = Some(idx + 1);
                break;
            }
            text_lines.push(lines[idx].to_string());
            idx += 1;
        }

        if text_lines.is_empty() {
            text_start_line = None;
            text_end_line = None;
        } else {
            text_start_line = Some(begin_marker_line + 1);
            text_end_line = Some(begin_marker_line + text_lines.len());
        }

        if text_end_marker_line.is_none() {
            diagnostic = Some(MetaDiagnostic {
                line: begin_marker_line,
                message: format!(
                    "meta text block for `{}` has no closing `----` marker",
                    comment.label
                ),
            });
        }
    }

    let references = comment
        .attrs
        .iter()
        .map(|attr| MetaReference {
            label: comment.label.clone(),
            role: if comment.kind == "source" && attr.role == "meta" {
                "source".to_string()
            } else {
                attr.role.clone()
            },
            binding_name: attr.binding_name.clone(),
            qualified_type: None,
            static_value: None,
            static_data: None,
            definition_file: None,
            definition_line: None,
            comment_line: comment.line,
            meta_role_types: BTreeSet::new(),
        })
        .collect();

    (
        MetaAnchor {
            kind: comment.kind.clone(),
            label: comment.label.clone(),
            references,
            comment_line: comment.line,
            text_begin_marker_line,
            text_end_marker_line,
            text_start_line,
            text_end_line,
            text: text_lines.join("\n"),
        },
        diagnostic,
    )
}

#[derive(Debug, Clone)]
struct MetaBindingDefinition {
    expr: Expr,
    annotated_type: Option<String>,
    definition_file: Option<String>,
    definition_line: usize,
}

#[derive(Clone)]
struct MetaCallableBranch {
    expressions: Vec<Expr>,
    bound_names: BTreeSet<String>,
    has_declared_effects: bool,
}

struct MetaGroundEvaluator {
    source_stmts: Vec<Stmt>,
    source_dir: Option<String>,
    initialized: bool,
    interpreter: Interpreter,
    env: Env,
    callables: BTreeMap<String, Vec<MetaCallableBranch>>,
    impure_names: BTreeSet<String>,
    evaluated_bindings: BTreeSet<String>,
    failed_bindings: BTreeSet<String>,
    visiting_bindings: BTreeSet<String>,
}

impl MetaGroundEvaluator {
    fn new(stmts: &[Stmt], source_dir: Option<&str>) -> Self {
        Self {
            source_stmts: stmts.to_vec(),
            source_dir: source_dir.map(str::to_string),
            initialized: false,
            interpreter: Interpreter::new(),
            env: Env::new(),
            callables: BTreeMap::new(),
            impure_names: BTreeSet::new(),
            evaluated_bindings: BTreeSet::new(),
            failed_bindings: BTreeSet::new(),
            visiting_bindings: BTreeSet::new(),
        }
    }

    fn ensure_initialized(&mut self) {
        if self.initialized {
            return;
        }
        let mut declarations = Vec::new();
        collect_meta_runtime_declarations(
            &self.source_stmts,
            self.source_dir.as_deref(),
            &mut BTreeSet::new(),
            &mut declarations,
        );
        let declarations = prepend_prelude(parse_prelude(), &declarations);
        let callables = collect_meta_runtime_callables(&declarations);
        let mut impure_names = meta_impure_runtime_names();
        for stmt in &declarations {
            if let Stmt::TypeDecl(TypeDecl::EffectDecl { ops, .. }) = stmt {
                impure_names.extend(ops.iter().map(|(name, _, _)| name.clone()));
            }
        }
        let mut interpreter = Interpreter::new();
        interpreter.suppress_output = true;
        interpreter.install_rule_dispatch_metadata_for_program(
            &self.source_stmts,
            self.source_dir.clone(),
        );
        let mut env = interpreter.default_env();
        interpreter.register_static_declarations(&declarations, &mut env);

        self.interpreter = interpreter;
        self.env = env;
        self.callables = callables;
        self.impure_names = impure_names;
        self.initialized = true;
    }

    fn resolve_expr(
        &mut self,
        expr: &Expr,
        bindings: &BTreeMap<String, &Expr>,
    ) -> Option<MetaValue> {
        self.ensure_initialized();
        let value = self.evaluate_expr(expr, bindings)?;
        runtime_value_to_meta_value(&value, &self.interpreter)
    }

    fn evaluate_expr(&mut self, expr: &Expr, bindings: &BTreeMap<String, &Expr>) -> Option<Value> {
        let mut dependencies = BTreeSet::new();
        let mut visiting_callables = BTreeSet::new();
        if !self.analyze_expr(
            expr,
            &BTreeSet::new(),
            bindings,
            &mut dependencies,
            &mut visiting_callables,
        ) {
            return None;
        }
        for dependency in dependencies {
            self.evaluate_binding(&dependency, bindings)?;
        }

        self.interpreter.step_count = 0;
        self.interpreter.step_limit = 1_000_000;
        self.interpreter.budget_exceeded = false;
        let evaluation = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            self.interpreter.eval(expr, &self.env)
        }));
        let budget_exceeded = self.interpreter.budget_exceeded;
        self.interpreter.step_limit = 0;
        self.interpreter.budget_exceeded = false;
        if budget_exceeded {
            None
        } else {
            evaluation.ok()
        }
    }

    fn evaluate_binding(&mut self, name: &str, bindings: &BTreeMap<String, &Expr>) -> Option<()> {
        if self.evaluated_bindings.contains(name) {
            return Some(());
        }
        if self.failed_bindings.contains(name) || !self.visiting_bindings.insert(name.to_string()) {
            return None;
        }
        let result = bindings
            .get(name)
            .and_then(|expr| self.evaluate_expr(expr, bindings))
            .map(|value| {
                self.env.set(name.to_string(), value);
                self.evaluated_bindings.insert(name.to_string());
            });
        self.visiting_bindings.remove(name);
        if result.is_none() {
            self.failed_bindings.insert(name.to_string());
        }
        result
    }

    fn analyze_expr(
        &self,
        expr: &Expr,
        bound_names: &BTreeSet<String>,
        bindings: &BTreeMap<String, &Expr>,
        dependencies: &mut BTreeSet<String>,
        visiting_callables: &mut BTreeSet<String>,
    ) -> bool {
        let mut referenced_names = BTreeSet::new();
        let mut safe = true;
        walk_ast_expr(expr, &mut |child| match child {
            AstChild::Expr(expr) => match &expr.kind {
                ExprKind::Var(name) => {
                    referenced_names.insert(name.clone());
                }
                ExprKind::Effect(_, _) | ExprKind::Handle { .. } => safe = false,
                _ => {}
            },
            AstChild::Stmt(stmt) => match stmt {
                Stmt::MonadicBind(..)
                | Stmt::StreamBind(..)
                | Stmt::For(..)
                | Stmt::While(..)
                | Stmt::Send(..)
                | Stmt::StreamSub(..)
                | Stmt::Prove { .. }
                | Stmt::Assert(..)
                | Stmt::Retract(..)
                | Stmt::Abort => safe = false,
                Stmt::Annot(name, _) if builtin_canonical(name) == "print" => safe = false,
                _ => {}
            },
        });
        if !safe {
            return false;
        }

        for name in referenced_names {
            if bound_names.contains(&name) {
                continue;
            }
            let canonical = builtin_canonical(&name);
            if self.impure_names.contains(&name) || self.impure_names.contains(canonical) {
                return false;
            }
            if bindings.contains_key(&name) {
                dependencies.insert(name.clone());
            }
            let Some(branches) = self.callables.get(&name) else {
                continue;
            };
            if !visiting_callables.insert(name.clone()) {
                continue;
            }
            for branch in branches {
                if branch.has_declared_effects {
                    return false;
                }
                for body in &branch.expressions {
                    if !self.analyze_expr(
                        body,
                        &branch.bound_names,
                        bindings,
                        dependencies,
                        visiting_callables,
                    ) {
                        return false;
                    }
                }
            }
            visiting_callables.remove(&name);
        }
        true
    }
}

fn collect_meta_runtime_declarations(
    stmts: &[Stmt],
    source_dir: Option<&str>,
    visited: &mut BTreeSet<String>,
    declarations: &mut Vec<Stmt>,
) {
    if let Some(source_dir) = source_dir {
        for stmt in stmts {
            let Stmt::Import(import_path) = stmt else {
                continue;
            };
            let Some(file_path) =
                Interpreter::resolve_import_path_for_source(import_path, source_dir)
            else {
                continue;
            };
            let canonical = std::fs::canonicalize(&file_path)
                .map(|path| path.to_string_lossy().to_string())
                .unwrap_or_else(|_| file_path.clone());
            if !visited.insert(canonical) {
                continue;
            }
            let Ok(imported_module) = parse_source_module_file_cached(Path::new(&file_path)) else {
                continue;
            };
            let imported_dir = std::path::Path::new(&file_path)
                .parent()
                .map(|parent| parent.to_string_lossy().to_string())
                .unwrap_or_else(|| ".".to_string());
            collect_meta_runtime_declarations(
                imported_module.statements(),
                Some(&imported_dir),
                visited,
                declarations,
            );
        }
    }

    declarations.extend(stmts.iter().filter_map(|stmt| match stmt {
        Stmt::Defn(_) | Stmt::TypeDecl(_) | Stmt::Rule(_) => Some(stmt.clone()),
        _ => None,
    }));
}

fn collect_meta_runtime_callables(stmts: &[Stmt]) -> BTreeMap<String, Vec<MetaCallableBranch>> {
    let mut callables = BTreeMap::new();
    for stmt in stmts {
        collect_meta_runtime_callable_from_stmt(stmt, &mut callables);
    }
    callables
}

fn collect_meta_runtime_callable_from_stmt(
    stmt: &Stmt,
    callables: &mut BTreeMap<String, Vec<MetaCallableBranch>>,
) {
    match stmt {
        Stmt::Defn(definition) => {
            collect_meta_runtime_callable_from_definition(definition, callables)
        }
        Stmt::Rule(rule) => {
            let (name, bound_names, expressions) = match rule {
                Rule::Clause { head, body } => (
                    meta_expr_name(head),
                    meta_rule_bound_names(head),
                    body.iter().cloned().collect(),
                ),
                Rule::Default {
                    head,
                    value,
                    condition,
                }
                | Rule::Exception {
                    head,
                    value,
                    condition,
                    ..
                } => {
                    let mut expressions = vec![value.clone()];
                    expressions.extend(condition.iter().cloned());
                    (
                        meta_expr_name(head),
                        meta_rule_bound_names(head),
                        expressions,
                    )
                }
                Rule::ReactiveScope { name, body } => {
                    for statement in body {
                        collect_meta_runtime_callable_from_stmt(statement, callables);
                    }
                    (Some(name.clone()), BTreeSet::new(), Vec::new())
                }
            };
            if let Some(name) = name {
                callables.entry(name).or_default().push(MetaCallableBranch {
                    expressions,
                    bound_names,
                    has_declared_effects: false,
                });
            }
        }
        Stmt::TypeDecl(TypeDecl::ADT { methods, .. })
        | Stmt::TypeDecl(TypeDecl::ImplBlock { methods, .. }) => {
            for method in methods {
                collect_meta_runtime_callable_from_definition(method, callables);
            }
        }
        Stmt::TypeDecl(TypeDecl::TraitDecl { methods, .. }) => {
            for method in methods {
                if let Some(body) = &method.default_body {
                    callables
                        .entry(method.name.clone())
                        .or_default()
                        .push(MetaCallableBranch {
                            expressions: vec![body.clone()],
                            bound_names: method
                                .params
                                .iter()
                                .map(|param| param.name.clone())
                                .collect(),
                            has_declared_effects: false,
                        });
                }
            }
        }
        Stmt::TypeDecl(TypeDecl::RuleScope { body, .. }) => {
            for statement in body {
                collect_meta_runtime_callable_from_stmt(statement, callables);
            }
        }
        _ => {}
    }
}

fn collect_meta_runtime_callable_from_definition(
    definition: &Defn,
    callables: &mut BTreeMap<String, Vec<MetaCallableBranch>>,
) {
    match definition {
        Defn::Fn {
            name,
            params,
            effects,
            body,
            ..
        } => {
            callables
                .entry(name.clone())
                .or_default()
                .push(MetaCallableBranch {
                    expressions: vec![body.clone()],
                    bound_names: params.iter().map(|param| param.name.clone()).collect(),
                    has_declared_effects: !effects.is_empty(),
                });
        }
        Defn::Module { body, .. } => {
            for statement in body {
                collect_meta_runtime_callable_from_stmt(statement, callables);
            }
        }
        Defn::Actor { .. } => {}
    }
}

fn meta_expr_name(expr: &Expr) -> Option<String> {
    match &expr.kind {
        ExprKind::App(function, _) => meta_expr_name(function),
        ExprKind::Var(name) => Some(name.clone()),
        _ => None,
    }
}

fn meta_rule_bound_names(head: &Expr) -> BTreeSet<String> {
    let ExprKind::App(_, arguments) = &head.kind else {
        return BTreeSet::new();
    };
    arguments
        .iter()
        .filter_map(|argument| {
            let argument = Interpreter::typed_rule_arg_parts(argument)
                .map(|(value, _)| value)
                .unwrap_or(argument);
            match &argument.kind {
                ExprKind::Var(name) => Some(name.clone()),
                _ => None,
            }
        })
        .collect()
}

