    #[test]
    fn checked_analysis_identity_covers_query_roots_but_excludes_proof_continuations() {
        let source = |continuation: &str| {
            format!(
                r#"
| eligible(value: Int) -> True under value > 0
| other(value: Int) -> True under value >= 0
? explore scan {{
    over eligible(value)
    find matches
    bounds {{
        value in [1, 2]
        fixed = 3
        where value >= 0
    }}
    boundaries on value by 1
    output {{
        key [bucket = value]
        extrema [measure = value + fixed, alternate = value]
        having varies(measure)
        show [shown = value]
        representative maximize shown
    }}
}}
| always: True -> True
? always -> {{ @ print("{continuation}") }}
"#
            )
        };
        let identity = |source: &str| {
            let statements = parse_test_program(&source).expect("parse analysis identity fixture");
            TypeChecker::check_with_artifacts(&statements, None, &source)
                .analysis_program
                .id
        };
        let baseline_source = source("first");
        let baseline = identity(&baseline_source);
        for (root, changed) in [
            (
                "question",
                baseline_source.replacen("over eligible(value)", "over other(value)", 1),
            ),
            (
                "polarity",
                baseline_source.replacen("find matches", "find violations", 1),
            ),
            (
                "domain",
                baseline_source.replacen("value in [1, 2]", "value in [1, 3]", 1),
            ),
            (
                "derived value",
                baseline_source.replacen("fixed = 3", "fixed = 4", 1),
            ),
            (
                "constraint",
                baseline_source.replacen("where value >= 0", "where value > 0", 1),
            ),
            (
                "boundary",
                baseline_source.replacen("boundaries on value by 1", "boundaries on value by 2", 1),
            ),
            (
                "key",
                baseline_source.replacen("bucket = value", "bucket = value + 1", 1),
            ),
            (
                "extrema",
                baseline_source.replacen("measure = value + fixed", "measure = value - fixed", 1),
            ),
            (
                "group filter",
                baseline_source.replacen("varies(measure)", "varies(alternate)", 1),
            ),
            (
                "shown value",
                baseline_source.replacen("shown = value", "shown = fixed", 1),
            ),
            (
                "representative",
                baseline_source.replacen("maximize shown", "minimize shown", 1),
            ),
        ] {
            assert_ne!(
                baseline,
                identity(&changed),
                "{root} must affect analysis identity"
            );
        }
        assert_eq!(
            baseline,
            identity(&source("second")),
            "proof presentation continuations do not rename Explore sites"
        );
    }

    #[test]
    fn explore_parser_builds_contextual_query_with_spans() {
        let source = r#"
? explore income_cliffs {
    over one_more_never_hurts(profile, income, step)
    find violations
    bounds {
        profile in [1, 2]
        income in range(0, 10)
        step = 1
        where income >= 0
    }
    boundaries on income by step
    output {
        key [income_before = income]
        extrema [income_gain = income + step - income]
        having varies(income_gain)
        show [income_after = income + step, profile]
        representative maximize income_after
    }
}
"#;
        let statements = parse_test_program(source).expect("parse exploration");
        let Stmt::Explore(query) = &statements[0] else {
            panic!("expected exploration, got {:?}", statements[0]);
        };
        assert_eq!(query.name.as_deref(), Some("income_cliffs"));
        assert_eq!(query.over.rule_name, "one_more_never_hurts");
        assert_eq!(
            query
                .over
                .inputs
                .iter()
                .map(|input| input.name.as_str())
                .collect::<Vec<_>>(),
            ["profile", "income", "step"]
        );
        assert_eq!(query.polarity, ExplorePolarity::Violations);
        assert_eq!(query.bounds.len(), 4);
        assert_eq!(
            query.boundary.as_ref().map(|item| item.axis.as_str()),
            Some("income")
        );
        assert_eq!(query.output.key.len(), 1);
        assert_eq!(query.output.extrema.len(), 1);
        assert!(matches!(
            &query.output.having,
            Some(ExploreHaving::Varies { extrema_name, .. })
                if extrema_name == "income_gain"
        ));
        assert_eq!(query.output.show.len(), 2);
        assert!(matches!(
            query.output.representative,
            ExploreRepresentative::Maximize { .. }
        ));
        assert!(!query.span.is_dummy());
        assert!(!query.over.span.is_dummy());
        assert!(query.over.inputs.iter().all(|input| !input.span.is_dummy()));
        assert!(query.bounds.iter().all(|bound| match bound {
            ExploreBound::Domain { domain, span, .. } => {
                !span.is_dummy() && !domain.span.is_dummy()
            }
            ExploreBound::Value { value, span, .. } => !span.is_dummy() && !value.span.is_dummy(),
            ExploreBound::Where {
                predicate, span, ..
            } => !span.is_dummy() && !predicate.span.is_dummy(),
        }));
        let boundary = query.boundary.as_ref().expect("boundary");
        assert!(!boundary.span.is_dummy());
        assert!(!boundary.step.span.is_dummy());
        assert!(!query.output.span.is_dummy());
        assert!(query
            .output
            .key
            .iter()
            .map(|field| (&field.value, field.span))
            .chain(
                query
                    .output
                    .extrema
                    .iter()
                    .map(|field| (&field.value, field.span)),
            )
            .chain(
                query
                    .output
                    .show
                    .iter()
                    .map(|field| (&field.value, field.span)),
            )
            .all(|(value, span)| !span.is_dummy() && !value.span.is_dummy()));
        assert!(query
            .output
            .having
            .as_ref()
            .is_some_and(|having| !having.span().is_dummy()));
        let ExploreRepresentative::Maximize { objective, span } = &query.output.representative
        else {
            unreachable!()
        };
        assert!(!span.is_dummy());
        assert!(!objective.span.is_dummy());
    }

    #[test]
    fn explore_parser_preserves_existing_proof_forms() {
        for source in [
            "? explore\n",
            "? explore: result\n",
            "? explore -> { = x = 1 }\n",
            "? explore else { = x = 1 }\n",
            "? explore by { | x -> refl }\n",
        ] {
            let statements = parse_test_program(source).expect(source);
            assert!(
                matches!(statements.first(), Some(Stmt::Prove { name, .. }) if name == "explore"),
                "proof form changed category: {source:?} => {:?}",
                statements.first()
            );
        }

        let words =
            "explore over find bounds boundaries output key extrema having varies show representative";
        let mut lexer = Lexer::new(words);
        let tokens = lexer.tokenize();
        let identifiers = tokens
            .iter()
            .filter(|token| token.kind != TokenKind::Eof)
            .map(|token| (token.source_text.as_str(), token.kind))
            .collect::<Vec<_>>();
        assert!(
            identifiers
                .iter()
                .all(|(_, kind)| *kind == TokenKind::Ident),
            "exploration clause words must remain contextual identifiers: {identifiers:?}"
        );
    }

    #[test]
    fn explore_parser_accepts_anonymous_query_and_rejects_structural_errors() {
        let anonymous = r#"
? explore {
    over condition(x)
    find matches
    bounds { x in [1] }
    output { key [x] representative first }
}
"#;
        let statements = parse_test_program(anonymous).expect("parse anonymous exploration");
        assert!(matches!(statements.first(), Some(Stmt::Explore(query)) if query.name.is_none()));

        for (source, expected) in [
            (
                "? explore bad { over p(x, x) find matches bounds { x in [1] } output { key [x] representative first } }",
                "duplicate exploration input `x`",
            ),
            (
                "? explore bad { over p(x, y) find matches bounds { x in [1] y = 1 } output { key [x] representative first } }",
                "must be separated by a newline or `;`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1]\nx = 1 } output { key [x] representative first } }",
                "duplicate exploration bound `x`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { key [] representative first } }",
                "at least one field",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { key [x] show [x] representative first } }",
                "output field `x` appears in both `key` and `show`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { key [x] extrema [x = 1] representative first } }",
                "output field `x` appears in both `key` and `extrema`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { key [x] having varies(x) representative first } }",
                "`having` requires a preceding nonempty `extrema` clause",
            ),
        ] {
            let error = parse_test_program(source).expect_err(source);
            assert!(
                error.contains(expected),
                "missing {expected:?} in {error:?} for {source:?}"
            );
        }

        for source in [
            "? explore lines { over p(x, y) find matches bounds { x in [1]\ny = 1 } output { key [x] representative first } }",
            "? explore semis { over p(x, y) find matches bounds { x in [1]; y = 1 } output { key [x] representative first } }",
        ] {
            parse_test_program(source).expect(source);
        }
    }

    #[test]
    fn explore_canonical_ast_walker_reaches_every_query_expression() {
        let source = r#"
? explore traversal {
    over condition(axis)
    find matches
    bounds {
        axis in explore_domain_marker
        derived = explore_value_marker
        where explore_where_marker
    }
    boundaries on axis by explore_step_marker
    output {
        key [key_value = explore_key_marker]
        extrema [extrema_value = explore_extrema_marker]
        having varies(extrema_value)
        show [shown_value = explore_show_marker]
        representative minimize explore_representative_marker
    }
}
"#;
        let statements = parse_test_program(source).expect("parse walker exploration");
        let mut visited = BTreeSet::new();
        walk_ast_stmt(&statements[0], &mut |child| {
            if let AstChild::Expr(Expr {
                kind: ExprKind::Var(name),
                ..
            }) = child
            {
                visited.insert(name.clone());
            }
        });
        for marker in [
            "explore_domain_marker",
            "explore_value_marker",
            "explore_where_marker",
            "explore_step_marker",
            "explore_key_marker",
            "explore_extrema_marker",
            "explore_show_marker",
            "explore_representative_marker",
        ] {
            assert!(
                visited.contains(marker),
                "walker missed {marker}: {visited:?}"
            );
        }
    }

    #[test]
    fn explore_parser_reports_clause_order_and_duplicate_clauses() {
        let cases = [
            (
                "? explore bad { find matches over p(x) bounds { x in [1] } output { key [x] representative first } }",
                "expected `over` in exploration, found `find`",
            ),
            (
                "? explore bad { over p(x) over p(x) find matches bounds { x in [1] } output { key [x] representative first } }",
                "expected `find` in exploration, found `over`",
            ),
            (
                "? explore bad { over p(x) bounds { x in [1] } find matches output { key [x] representative first } }",
                "expected `find` in exploration, found `bounds`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } boundaries on x by 1 boundaries on x by 1 output { key [x] representative first } }",
                "expected `output` in exploration, found `boundaries`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { show [x] key [x] representative first } }",
                "expected `key` in exploration output, found `show`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { key [x] key [x] representative first } }",
                "expected `representative` in exploration output, found `key`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { key [x] show [shown = x] show [again = x] representative first } }",
                "expected `representative` in exploration output, found `show`",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { key [x] representative first representative first } }",
                "unexpected `representative` after exploration representative",
            ),
            (
                "? explore bad { over p(x) find matches bounds { x in [1] } output { key [x] representative first } output { key [x] representative first } }",
                "unexpected exploration clause `output` after `output`",
            ),
        ];

        for (source, expected) in cases {
            let error = parse_test_program(source).expect_err(source);
            assert!(
                error.contains(expected),
                "missing {expected:?} in {error:?} for {source:?}"
            );
        }
    }

    #[test]
    fn explore_typechecker_builds_exact_typed_query_ir() {
        let source = r#"
# Profile = Worker | Student

> next_income(income: Int, step: Int) -> Int { income + step }
| one_more_never_hurts(profile: Profile, income: Int, step: Int) -> next_income(income, step) >= income

? explore income_cliffs {
    over one_more_never_hurts(profile, income, step)
    find violations
    bounds {
        profile in values(Profile)
        income in range(0, 10)
        step = 1
        where income >= 0
    }
    boundaries on income by step
    output {
        key [income_before = income]
        extrema [income_gain = next_income(income, step) - income]
        having varies(income_gain)
        show [
            income_after = next_income(income, step),
            reported_gain = income_gain
        ]
        representative maximize income_gain
    }
}
"#;
        let artifacts = explore_artifacts_for_source(source);
        assert!(
            artifacts.diagnostics.is_empty(),
            "{:?}",
            artifacts.diagnostics
        );
        assert_eq!(artifacts.exploration_queries.len(), 1);
        let query = &artifacts.exploration_queries[0];
        assert_eq!(query.name.as_deref(), Some("income_cliffs"));
        assert_eq!(query.rule_name, "one_more_never_hurts");
        assert_eq!(query.rule_arity, 3);
        assert_eq!(query.polarity, ExplorePolarity::Violations);
        assert_eq!(
            query
                .inputs
                .iter()
                .map(|input| (input.name.as_str(), input.ty.to_string()))
                .collect::<Vec<_>>(),
            [
                ("profile", "Profile".to_string()),
                ("income", "Int".to_string()),
                ("step", "Int".to_string()),
            ]
        );
        assert!(matches!(
            &query.bounds[0],
            TypedExploreBound::Domain {
                domain: TypedExploreDomain::Values { ty }, ..
            } if ty.to_string() == "Profile"
        ));
        assert!(matches!(
            &query.bounds[1],
            TypedExploreBound::Domain {
                domain: TypedExploreDomain::Range { .. },
                ..
            }
        ));
        assert!(matches!(
            &query.bounds[2],
            TypedExploreBound::Value { value_ty, .. } if value_ty.to_string() == "Int"
        ));
        assert_eq!(
            query.boundary.as_ref().map(|boundary| (
                boundary.axis.as_str(),
                boundary.axis_ty.to_string(),
                boundary.step_ty.to_string(),
            )),
            Some(("income", "Int".to_string(), "Int".to_string()))
        );
        assert_eq!(query.output.key[0].ty.to_string(), "Int");
        assert_eq!(query.output.extrema[0].ty.to_string(), "Int");
        assert!(matches!(
            &query.output.having,
            Some(TypedExploreHaving::Varies {
                extrema_name,
                extrema_index: 0,
                ..
            }) if extrema_name == "income_gain"
        ));
        assert_eq!(query.output.show[0].ty.to_string(), "Int");
        assert_eq!(query.output.show[1].ty.to_string(), "Int");
        assert_eq!(
            query
                .output
                .representative_ty
                .as_ref()
                .map(ToString::to_string),
            Some("Int".to_string())
        );
    }

    #[test]
    fn checked_finite_plan_digest_frames_recursive_collections() {
        fn digest(plan: &explore::ExploreFiniteTypePlan) -> Box<str> {
            let mut hasher = Sha256::new();
            hasher.update(b"futuruna.checked-finite-plan-canary.v1\0");
            hash_checked_finite_plan(&mut hasher, plan);
            format!("{:x}", hasher.finalize()).into_boxed_str()
        }

        let left = explore::ExploreFiniteTypePlan::Tuple {
            elements: vec![
                explore::ExploreFiniteTypePlan::Tuple {
                    elements: vec![explore::ExploreFiniteTypePlan::Unit],
                    cardinality: explore::ExploreCardinality::Exact(1),
                },
                explore::ExploreFiniteTypePlan::Unit,
            ],
            cardinality: explore::ExploreCardinality::Exact(1),
        };
        let right = explore::ExploreFiniteTypePlan::Tuple {
            elements: vec![explore::ExploreFiniteTypePlan::Tuple {
                elements: vec![
                    explore::ExploreFiniteTypePlan::Unit,
                    explore::ExploreFiniteTypePlan::Unit,
                ],
                cardinality: explore::ExploreCardinality::Exact(1),
            }],
            cardinality: explore::ExploreCardinality::Exact(1),
        };
        assert_ne!(digest(&left), digest(&right));
    }

    #[test]
    fn checked_explore_query_artifact_binds_occurrence_sites_universe_and_digest() {
        let source = r#"
# Profile = Worker | Student
| eligible(profile: Profile, baseline: Profile, income: Int) -> income >= 0
? explore scan {
    over eligible(profile, baseline, income)
    find matches
    bounds {
        profile in values(Profile)
        baseline = Worker
        income in range(0, 3)
    }
    boundaries on income by 1
    output { key [profile, income] representative first }
}
"#;
        let mut artifacts = explore_artifacts_for_source(source);
        assert!(
            artifacts.diagnostics.is_empty(),
            "{:?}",
            artifacts.diagnostics
        );
        let (digest, declaration) = {
            let checked = artifacts
                .checked_exploration_query(0)
                .expect("producer-minted checked query");
            assert_eq!(checked.artifact.identity.digest.len(), 64);
            assert_eq!(
                checked.artifact.identity.analysis_program,
                artifacts.analysis_program.id
            );
            assert_eq!(checked.artifact.sites.bounds.len(), 3);
            assert!(checked.artifact.sites.bounds[0].binder.is_some());
            assert!(checked.artifact.sites.boundary_step.is_some());
            assert_eq!(checked.artifact.sites.key.len(), 2);
            assert_eq!(checked.artifact.type_facts.len(), 3);
            assert_eq!(checked.artifact.ground_constructors.len(), 3);
            assert_eq!(checked.artifact.finite_plan_facts.len(), 1);
            assert!(checked
                .artifact
                .ground_constructors
                .iter()
                .any(|constructor| {
                    matches!(
                        &constructor.site,
                        CheckedExploreGroundConstructorSite::FixedFact {
                            fact_index: 0,
                            value_path,
                        } if value_path.is_empty()
                    ) && constructor.constructor.variant.as_ref() == "Worker"
                        && constructor.constructor.variant_index == 0
                        && matches!(
                            &constructor.constructor.as_ref().owner,
                            CheckedDataTypeId::Declared(owner)
                                if owner.declaration.name.as_ref() == "Profile"
                        )
                }));
            assert_eq!(checked.closed_query.universe.dimensions.len(), 2);
            (
                checked.artifact.identity.digest.clone(),
                checked.artifact.identity.declaration.clone(),
            )
        };
        assert_eq!(
            artifacts
                .checked_exploration_query_for_declaration(&declaration)
                .expect("exact declaration occurrence")
                .artifact
                .identity
                .digest
                .as_ref(),
            digest.as_ref()
        );
        let original_plan =
            match &mut artifacts.exploration_universes[0].universe.dimensions[0].domain {
                explore::ExploreExactDomain::FiniteType { plan, .. } => {
                    std::mem::replace(plan, explore::ExploreFiniteTypePlan::Bool)
                }
                _ => panic!("Profile dimension uses a finite-type plan"),
            };
        assert!(matches!(
            artifacts.checked_exploration_query(0),
            Err(CheckedExploreQueryAccessError::ArtifactDiverged)
        ));
        match &mut artifacts.exploration_universes[0].universe.dimensions[0].domain {
            explore::ExploreExactDomain::FiniteType { plan, .. } => *plan = original_plan,
            _ => unreachable!("Profile dimension remains finite"),
        }
        artifacts.exploration_universes[0].query.polarity = ExplorePolarity::Violations;
        assert!(matches!(
            artifacts.checked_exploration_query(0),
            Err(CheckedExploreQueryAccessError::ArtifactDiverged)
        ));
        assert_eq!(digest.len(), 64);
    }

    #[test]
    fn checked_constructor_provenance_binds_owner_layout_fields_and_patterns() {
        let source = r#"
# Record(value: Int)
# Event = Open(code: Int) | Closed(reason: String)
> record_value(record: Record) -> Int { record.value }
> make_open() -> Event { Open(1) }
> event_code(event: Event) -> Int {
    match event {
        | Open(code) -> code
        | Closed(_) -> 0
    }
}
"#;
        let artifacts = explore_artifacts_for_source(source);
        assert!(
            artifacts.diagnostics.is_empty(),
            "{:?}",
            artifacts.diagnostics
        );
        let event = artifacts
            .analysis_program
            .declarations
            .iter()
            .find(|declaration| declaration.id.name.as_ref() == "Event")
            .expect("Event declaration");
        let event_owner =
            CheckedDataTypeId::Declared(CheckedDeclarationOccurrenceId::from_sourced(event));
        let open = artifacts
            .checked_resolutions
            .expressions
            .values()
            .filter_map(|resolution| resolution.exact_constructor.as_ref())
            .find(|constructor| constructor.variant.as_ref() == "Open")
            .expect("exact Open constructor expression");
        assert_eq!(open.owner, event_owner);
        assert_eq!(open.variant_index, 0);
        assert_eq!(open.layout, CheckedConstructorLayout::Named);
        assert_eq!(open.fields.len(), 1);
        assert_eq!(open.fields[0].name.as_ref(), "code");
        assert!(artifacts
            .checked_resolutions
            .constructor_patterns
            .values()
            .any(|pattern| {
                pattern.constructor.owner == event_owner
                    && pattern.constructor.variant.as_ref() == "Open"
                    && pattern.source_fields.as_ref() == open.fields.as_ref()
            }));
        assert!(artifacts
            .checked_resolutions
            .expressions
            .values()
            .any(|resolution| {
                matches!(
                    &resolution.field,
                    Some(CheckedFieldResolution::Data { fields, .. })
                        if fields.len() == 1
                            && fields[0].identity.name.as_ref() == "value"
                            && fields[0].layout == CheckedConstructorLayout::Named
                )
            }));
    }

    #[test]
    fn explore_typechecker_accepts_workbook_helper_functions() {
        let source = r#"
# Household = Single | Couple

> support(household: Household, income: Int) -> Int {
    if income < 100000 {
        match household {
            | Single -> 10000
            | Couple -> 15000
        }
    } else {
        0
    }
}
> available_resources(household: Household, income: Int) -> Int {
    income + support(household, income)
}
> loss_after_next_step(household: Household, income: Int, step: Int) -> Int {
    available_resources(household, income) - available_resources(household, income + step)
}
| next_step_never_hurts(household: Household, income: Int, step: Int) -> available_resources(household, income + step) >= available_resources(household, income)

? explore support_cliffs {
    over next_step_never_hurts(household, income, step)
    find violations
    bounds {
        household in values(Household)
        income in range(90000, 110000)
        step = 1
    }
    boundaries on income by step
    output {
        key [income_before = income]
        show [
            income_after = income + step,
            household,
            available_before = available_resources(household, income),
            available_after = available_resources(household, income + step),
            loss = loss_after_next_step(household, income, step)
        ]
        representative maximize loss
    }
}
"#;
        let artifacts = explore_artifacts_for_source(source);
        assert!(
            artifacts.diagnostics.is_empty(),
            "{:?}",
            artifacts.diagnostics
        );
        let query = artifacts
            .exploration_queries
            .first()
            .expect("typed workbook exploration");
        assert_eq!(query.output.show.len(), 5);
        assert_eq!(query.output.show[2].ty.to_string(), "Int");
        assert_eq!(query.output.show[3].ty.to_string(), "Int");
        assert_eq!(query.output.show[4].ty.to_string(), "Int");
        assert_eq!(
            query
                .output
                .representative_ty
                .as_ref()
                .map(ToString::to_string),
            Some("Int".to_string())
        );
    }

